struct Aura{GuidList targets;int32 duration=1000;GuidList GetEffectTargets(){return targets;}void RemoveEffectTarget(ObjectGuid g){targets.remove(g);}void AddEffectTarget(ObjectGuid g){targets.push_back(g);}int32 GetDuration(){return duration;}void SetDuration(int32 d){duration=d;}};
