struct Unit:WorldObject{uint64 health=100,maxHealth=100;ObjectGuid guid=1;float distance=25;bool pvp=false;uint32 history=0;std::map<uint32,AuraEffect>effects;std::set<uint32>auras;Unit*ToUnit()override{return this;}virtual Player*ToPlayer(){return nullptr;}uint64 GetMaxHealth(){return maxHealth;}uint64 GetHealth(){return health;}uint64 CountPctFromMaxHealth(int32 pct){return CalculatePct(maxHealth,pct);}ObjectGuid GetGUID(){return guid;}float GetDistance(Unit*){return distance;}bool HasAura(uint32 id,ObjectGuid=0){return auras.count(id)!=0;}AuraEffect*GetAuraEffect(uint32 id,uint32){auto it=effects.find(id);return it==effects.end()?nullptr:&it->second;}Aura*GetAura(uint32 id){auto e=GetAuraEffect(id,0);return e?e->GetBase():nullptr;}void CastCustomSpell(Unit*target,uint32 id,float*amount,void*,void*,bool){casts.push_back({this,target,id,*amount});}void CastCustomSpell(uint32 id,uint32,int32 amount,Unit*target,bool){casts.push_back({this,target,id,float(amount)});}void CastSpell(Unit*target,uint32 id,bool){casts.push_back({this,target,id,0});}bool CanPvPScalar(){return pvp;}uint32 GetDamageTakenInPastSecs(uint32,bool,bool){return history;}};
