static void Anvil(){spell_activate_closes_anvil_SpellScript script;WorldObject a,b,unrelated;std::list<WorldObject*>all;for(uint32 id:{uint32(GO_THUNDER_FORGE_AVNIL),uint32(GO_THUNDER_FORGE_AVNIL_2),uint32(GO_THUNDER_FORGE_AVNIL_3),uint32(GO_THUNDER_FORGE_AVNIL_4),uint32(GO_THUNDER_FORGE_AVNIL_5),uint32(GO_THUNDER_FORGE_AVNIL_6),uint32(GO_THUNDER_FORGE_AVNIL_7)}){a.entry=id;all={&a,&unrelated};script.FilterTargets(all);Require(all.size()==1&&all.front()==&a,"Each authored anvil survives remove_if;unrelated object rejected");}a.entry=NPC_ANVIL_STALKER;b.entry=0;all={&a,&b};script.FilterTargets2(all);Require(all.size()==1&&all.front()==&a,"Separate stalker effect admission retained");all.clear();script.FilterTargets(all);Require(all.empty(),"No invented anvil when absent");}
static void Electric(){spell_electric_discharge_SpellScript script;WorldObject a,other;for(uint32 id:{uint32(NPC_SHA_AMALGAMATION),uint32(NPC_SHA_FIEND),uint32(NPC_SHA_BEAST)}){a.entry=id;std::list<WorldObject*>targets={&a,&other};script.FilterTargets(targets);Require(targets.size()==1&&targets.front()==&a,"Each native sha survives Electric Discharge admission");}}
static void Azerite(){AzeriteFrame frame;for(uint32 id:{uint32(GameObjects::Azerite),uint32(GameObjects::Azerite2)}){GameObject go;go.entry=id;frame.OnGameObjectCreate(&go);Require(frame.initialized>0&&go.queue.size()==1&&go.queue[0].first==3000&&!go.animations,"Either actual Azerite variant initializes immediately and retains3s animation");go.queue[0].second();Require(go.animations==1,"Authored animation payload retained");}GameObject other;other.entry=1;auto before=frame.initialized;frame.OnGameObjectCreate(&other);Require(frame.initialized==before&&other.queue.empty(),"Unrelated gameobject cannot become capture node");}
static void Guardian(){Unit caster,target;spell_pri_guardian_spirit_AuraScript script;script.caster=&caster;script.target=&target;script.info.storage[1].value=40;Require(script.Load(),"Native heal-percent load");target.maxHealth=10000000000ull;target.health=1;DamageInfo hit{1};float absorb=0;script.Absorb(nullptr,hit,absorb);Require(script.removed&&casts.size()==1&&casts[0].spell==48153&&casts[0].amount==4000000000.f&&absorb==1,"Lethal Guardian Spirit retains40percent maximum-health heal beyond signed32");casts.clear();script.removed=false;target.health=100;script.Absorb(nullptr,hit,absorb);Require(casts.empty()&&!script.removed,"Nonlethal hit cannot consume rescue");}
static void Shell(){Unit caster,target;spell_pri_spirit_shell_SpellScript script;script.caster=&caster;script.target=&target;caster.auras.insert(109964);target.maxHealth=10000000000ull;script.Configure(7000000000ull);script.HandleOnHit();Require(casts.size()==1&&casts[0].spell==114908&&std::abs(casts[0].amount-6000000000.f)<=1024.f&&script.GetHitHeal64()==0,"Spirit Shell caps native wide heal atpositive60percent and converts rather than direct heal");casts.clear();caster.auras.clear();script.Configure(100);script.HandleOnHit();Require(casts.empty()&&script.GetHitHeal64()==100,"Outside Spirit Shell retain direct heal");}
static void Halo(){Unit caster,target;spell_pri_halo_heal_SpellScript script;script.caster=&caster;script.target=&target;for(float distance:{0.f,10.f,25.f,40.f}){caster.distance=distance;uint64 input=5000000000ull;script.Configure(input);script.HandleHeal(0);float pct=0.5f*pow(1.01f,-pow((distance-25.f)/2,4))+0.1f+0.015f*distance;auto expected=HealingAmount::Apply(input,0,pct);Require(script.GetHitHeal64()==expected&&expected>0,"Halo retains native64 channel and exact authored distance factor");}for(uint64 input:{1ull,100ull,12345ull}){caster.distance=25;script.Configure(input,false);script.HandleHeal(0);Require(script.GetHitHeal64()==uint64(float(input)*0.975f),"Ordinary legacy heal retains former per-target rounding");}}
static void Penance(){Unit caster,target;caster.effects[198069].amount=50;spell_pri_penance_heal script;script.caster=&caster;script.target=&target;for(uint64 input:{100ull,2147483647ull,5000000000ull,UINT64_MAX}){script.Configure(input);script.HandleHeal(0);auto expected=HealingAmount::Add(input,CalculatePct(input,50.f));Require(script.GetHitHeal64()==expected,"Penance50percent bonus retains exact wide channel with bounded addition");}caster.effects.clear();script.Configure(5000000000ull);script.HandleHeal(0);Require(script.GetHitHeal64()==5000000000ull,"Absent DarkSide aura leaves native heal unchanged");}
static void Chain(){Unit caster,target;caster.effects[200076].amount=20;spell_sha_chain_heal script;script.caster=&caster;script.target=&target;script.Configure(5000000000ull);script.HandleHeal(0);Require(script.GetHitHeal64()==5000000000ull,"Missing own HoT cannot grant Deluge");target.auras.insert(61295);script.HandleHeal(0);Require(std::abs(double(script.GetHitHeal64())-6000000000.)<=1024.,"Own HoT Deluge retains full20percent bonus above signed32");script.Configure(UINT64_MAX);script.HandleHeal(0);Require(script.GetHitHeal64()==UINT64_MAX,"Deluge addition saturates native64 domain");}
static void Ancestral(){Unit caster;spell_sha_ancestral_guidance script;AuraEffect effect;effect.amount=20;HealInfo heal{5000000000ull};DamageInfo hit{6000000000ull};ProcEventInfo event;event.actor=&caster;event.heal=&heal;Require(script.CheckProc(event),"Real positive heal admitted");script.HandleProc(&effect,event);Require(script.prevented&&casts.size()==1&&casts[0].amount==1000000000.f,"Ancestral Guidance retains full64 heal amount before20percent conversion");casts.clear();event.heal=nullptr;event.damage=&hit;Require(script.CheckProc(event),"Real positive damage admitted");script.HandleProc(&effect,event);Require(casts.size()==1&&casts[0].amount==1200000000.f,"Damage branch retains full native64 source");Spell nested;nested.info.Id=114911;event.spell=&nested;Require(!script.CheckProc(event),"Guidance heal cannot recursively proc itself");}
static void DeathStrike(){Unit caster,target;spell_dk_death_strike_SpellScript script;script.caster=&caster;script.target=&target;caster.maxHealth=50000000000ull;script.info.storage[2].value=20;script.info.storage[3].value=5;script.info.storage[4].value=10;script.HandleHeal(0);Require(casts.size()==1&&casts[0].spell==SPELL_DK_DEATH_STRIKE_HEAL&&casts[0].amount==5000000000.f,"Death Strike10percent minimum reaches native float child without signed32 truncation");casts.clear();caster.maxHealth=1000;caster.history=10000;script.HandleHeal(0);Require(casts[0].amount==2000,"Native history branch retains20percent choice");casts.clear();caster.pvp=true;script.HandleHeal(0);Require(casts[0].amount==1000,"Native PvP history reduction preserved");}
int main(int argc,char**argv){try{Require(argc==2,"Case required");switch(std::stoul(argv[1])){case 0:Anvil();break;case 1:Electric();break;case 2:Azerite();break;case 3:Guardian();break;case 4:Shell();break;case 5:Halo();break;case 6:Penance();break;case 7:Chain();break;case 8:Ancestral();break;case 9:DeathStrike();break;default:throw std::runtime_error("Unknown case");}std::cout<<"PASS complete production sixth class/create-hook;controlled cast/aura/spatial endpoints,native metadata/dispatcher separate,client pending\n";return 0;}catch(std::exception const&e){std::cerr<<e.what()<<'\n';return 1;}}
